insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('6505fb8a-c88c-4232-b41b-5c8c28f1e37d', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', null, 'topic'::public.curated_course_node_type, 'Strategic Management, Integrative Thinking, and Strategic Diagnosis', 'Strategic management asks how a hospitality enterprise can create durable value when guests, competitors, assets, talent, technology, capital, and institutions are changing. This opening section establishes a disciplined process for diagnosis, choice, execution, and learning.', 0),
  ('f5c7de7f-481d-4368-8770-b2bc707b1763', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '6505fb8a-c88c-4232-b41b-5c8c28f1e37d', 'subtopic'::public.curated_course_node_type, 'The work of strategy', 'Students distinguish strategy from goals, budgets, operational excellence, slogans, and isolated initiatives.', 0),
  ('4c1fe305-afa1-4d74-a714-ad35fbdb0586', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'f5c7de7f-481d-4368-8770-b2bc707b1763', 'concept'::public.curated_course_node_type, 'Mission, purpose, vision, values, objectives, strategy, policy, tactics, operating plan, and business model', null, 0),
  ('d29c2a50-8919-471f-914e-2e8763d287ee', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'f5c7de7f-481d-4368-8770-b2bc707b1763', 'concept'::public.curated_course_node_type, 'Diagnosis, guiding policy, coherent action, choice, tradeoff, fit, positioning, advantage, and renewal', null, 1),
  ('c7b6bec9-5b53-4be2-887b-2f73e44beda4', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'f5c7de7f-481d-4368-8770-b2bc707b1763', 'concept'::public.curated_course_node_type, 'Corporate, business-unit, brand, property, function, platform, destination, and ecosystem levels', null, 2),
  ('92c96383-1c8a-439b-a23d-1149cb6dba8e', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '6505fb8a-c88c-4232-b41b-5c8c28f1e37d', 'subtopic'::public.curated_course_node_type, 'Strategic problem framing', 'This subtopic turns an ambiguous management situation into the key question, decision, evidence needs, alternatives, and criteria.', 1),
  ('2d1c413a-3186-4883-8632-50105754358f', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '92c96383-1c8a-439b-a23d-1149cb6dba8e', 'concept'::public.curated_course_node_type, 'Symptoms versus causes, issue trees, hypotheses, assumptions, constraints, uncertainties, and decision rights', null, 0),
  ('f8d840ca-d8f1-464a-b66d-147619aaaae7', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '92c96383-1c8a-439b-a23d-1149cb6dba8e', 'concept'::public.curated_course_node_type, 'Relevant time horizon, unit of analysis, stakeholder perspectives, boundaries, counterfactual, and opportunity cost', null, 1),
  ('6539d3e7-80ac-4315-bb45-7b0b07f585d4', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '92c96383-1c8a-439b-a23d-1149cb6dba8e', 'concept'::public.curated_course_node_type, 'Facts, estimates, forecasts, scenarios, inference, judgment, bias, and confidence', null, 2),
  ('d6f91b9f-60cd-46d9-8dff-e5d8d5c46afc', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '6505fb8a-c88c-4232-b41b-5c8c28f1e37d', 'subtopic'::public.curated_course_node_type, 'Integrated hospitality diagnosis', 'Students connect marketing, operations, people, technology, finance, real estate, law, and sustainability into one enterprise view.', 2),
  ('78459be8-449f-4846-981f-f99a026da493', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'd6f91b9f-60cd-46d9-8dff-e5d8d5c46afc', 'concept'::public.curated_course_node_type, 'Guest promise, service system, demand, capacity, channel, labor, asset, capital, owner, and community linkages', null, 0),
  ('596991e1-7e0c-486c-9d6f-c51c4df8a039', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'd6f91b9f-60cd-46d9-8dff-e5d8d5c46afc', 'concept'::public.curated_course_node_type, 'Key performance drivers, reinforcing loops, bottlenecks, tensions, second-order effects, and unintended consequences', null, 1),
  ('beab762e-dd36-4a53-bbd4-e3692e0cbb47', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'd6f91b9f-60cd-46d9-8dff-e5d8d5c46afc', 'concept'::public.curated_course_node_type, 'Strategic narrative, evidence table, material issues, priorities, and concise executive problem statement', null, 2),
  ('5c9ea195-3358-48b1-955a-02bb4c7987aa', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', null, 'topic'::public.curated_course_node_type, 'External Environment, Industry Structure, and Hospitality Ecosystems', 'No firm chooses strategy in a vacuum. Students assess macro forces, industry economics, competitors, complementors, platforms, regulators, and local stakeholders to identify structural opportunities and threats.', 1),
  ('c990ae6f-5378-4f6d-bcbe-2a537fc5ee98', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '5c9ea195-3358-48b1-955a-02bb4c7987aa', 'subtopic'::public.curated_course_node_type, 'Macroenvironment and scenarios', 'Students examine forces that can reshape demand, cost, access, investment, and legitimacy.', 0),
  ('f8f56e67-903f-4682-833f-894de285733d', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'c990ae6f-5378-4f6d-bcbe-2a537fc5ee98', 'concept'::public.curated_course_node_type, 'Political, economic, social, technological, environmental, and legal analysis', null, 0),
  ('ca3b7937-fe1b-4bef-b0b4-2f77047e2fa7', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'c990ae6f-5378-4f6d-bcbe-2a537fc5ee98', 'concept'::public.curated_course_node_type, 'Demographics, mobility, work patterns, inflation, labor, interest rates, health, climate, geopolitics, and regulation', null, 1),
  ('5efc4354-11ac-428b-bdd5-0ca8d3530efc', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'c990ae6f-5378-4f6d-bcbe-2a537fc5ee98', 'concept'::public.curated_course_node_type, 'Predetermined elements, critical uncertainties, weak signals, scenario axes, narratives, implications, and signposts', null, 2),
  ('d64518f2-a873-4fcf-9d5b-75b2fc93e784', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '5c9ea195-3358-48b1-955a-02bb4c7987aa', 'subtopic'::public.curated_course_node_type, 'Industry structure and profit pools', 'This subtopic explains how bargaining power, rivalry, entry, substitutes, complements, and capacity shape value capture.', 1),
  ('4188a654-05fb-40f9-8937-75af91e85693', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'd64518f2-a873-4fcf-9d5b-75b2fc93e784', 'concept'::public.curated_course_node_type, 'Five forces, market definition, strategic groups, concentration, entry barriers, switching costs, and exit barriers', null, 0),
  ('3ecaa984-f76d-499f-9ecc-730460b47c72', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'd64518f2-a873-4fcf-9d5b-75b2fc93e784', 'concept'::public.curated_course_node_type, 'Brand, owner, operator, franchisee, landlord, lender, OTA, GDS, supplier, employee, and guest bargaining power', null, 1),
  ('9dc5858a-200d-49ff-a244-23be9a2e6676', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'd64518f2-a873-4fcf-9d5b-75b2fc93e784', 'concept'::public.curated_course_node_type, 'Revenue pools, cost pools, margin pools, channel leakage, asset intensity, cycle, maturity, and structural change', null, 2),
  ('b9d89191-c4f4-4dab-8ebc-02990332564c', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '5c9ea195-3358-48b1-955a-02bb4c7987aa', 'subtopic'::public.curated_course_node_type, 'Competitors, platforms, and ecosystems', 'Students analyze rivalry and collaboration across interconnected hospitality and travel systems.', 2),
  ('19466fa4-e6fd-428c-b6d8-cedac480f06c', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'b9d89191-c4f4-4dab-8ebc-02990332564c', 'concept'::public.curated_course_node_type, 'Competitive set, strategic-group map, benchmarking, relative cost, differentiation, moves, countermoves, and game theory', null, 0),
  ('9caeed64-b88a-47e9-b2c8-0a5ebf99ff65', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'b9d89191-c4f4-4dab-8ebc-02990332564c', 'concept'::public.curated_course_node_type, 'Airlines, destinations, attractions, mobility, payment, loyalty, technology, media, food delivery, and experience partners', null, 1),
  ('db65d5ba-67b2-4825-b481-56e228539be0', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'b9d89191-c4f4-4dab-8ebc-02990332564c', 'concept'::public.curated_course_node_type, 'Network effects, standards, data access, multihoming, orchestration, complementors, coopetition, and ecosystem health', null, 2),
  ('b4bacfc9-3e5a-457d-a8e0-3d84f7a625b4', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', null, 'topic'::public.curated_course_node_type, 'Resources, Capabilities, Value Chains, and Organizational Advantage', 'External opportunity matters only when the organization can act. Students identify the tangible, intangible, human, relational, and organizational resources that produce distinctive guest and financial outcomes.', 2),
  ('77f1f73f-670a-47b0-ab90-d93981b34370', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'b4bacfc9-3e5a-457d-a8e0-3d84f7a625b4', 'subtopic'::public.curated_course_node_type, 'Resource and capability analysis', 'Students evaluate what the enterprise owns, accesses, coordinates, learns, and protects.', 0),
  ('ee8d759c-f9d3-416b-88d8-12233080adc9', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '77f1f73f-670a-47b0-ab90-d93981b34370', 'concept'::public.curated_course_node_type, 'Physical assets, locations, capital, data, technology, brands, contracts, intellectual property, culture, talent, and relationships', null, 0),
  ('c1a06fbf-da54-426e-82b9-3298d846e530', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '77f1f73f-670a-47b0-ab90-d93981b34370', 'concept'::public.curated_course_node_type, 'Resource versus capability, routines, systems, dynamic capabilities, absorptive capacity, learning, and path dependence', null, 1),
  ('99492fba-a38b-4898-9346-860c4046cb23', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '77f1f73f-670a-47b0-ab90-d93981b34370', 'concept'::public.curated_course_node_type, 'Value, rarity, imitability, organization, durability, transferability, substitutability, and appropriation', null, 2),
  ('7a6bdff8-08b7-4534-b5de-f630b64223f8', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'b4bacfc9-3e5a-457d-a8e0-3d84f7a625b4', 'subtopic'::public.curated_course_node_type, 'Value chain and activity-system analysis', 'This subtopic maps how activities combine to deliver the guest promise and where cost, quality, speed, risk, and differentiation arise.', 1),
  ('baf1096a-ed7c-4eaf-a846-701dac0c3536', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '7a6bdff8-08b7-4534-b5de-f630b64223f8', 'concept'::public.curated_course_node_type, 'Development, procurement, distribution, marketing, booking, arrival, operations, service, recovery, loyalty, and support activities', null, 0),
  ('e5d5ef2f-14c2-46e1-8bf3-27cedb4f655d', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '7a6bdff8-08b7-4534-b5de-f630b64223f8', 'concept'::public.curated_course_node_type, 'Outsource versus own, shared services, clusters, centralization, local adaptation, interfaces, handoffs, and bottlenecks', null, 1),
  ('0e2b32a7-9518-40d9-9908-58c76119eb15', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '7a6bdff8-08b7-4534-b5de-f630b64223f8', 'concept'::public.curated_course_node_type, 'Activity fit, complementarities, tradeoffs, cost drivers, willingness-to-pay drivers, leakage, and redesign', null, 2),
  ('29c08560-35ac-40b1-be00-65c99cf91296', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'b4bacfc9-3e5a-457d-a8e0-3d84f7a625b4', 'subtopic'::public.curated_course_node_type, 'People, culture, and relational capability', 'Students treat service culture and stakeholder relationships as strategic systems rather than soft background conditions.', 2),
  ('159ed741-16ad-4e38-9478-a6a052277569', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '29c08560-35ac-40b1-be00-65c99cf91296', 'concept'::public.curated_course_node_type, 'Leadership, psychological safety, employee value proposition, skills, staffing model, incentives, voice, and retention', null, 0),
  ('29a0a352-263c-49c3-a8ab-f95e01f4e4af', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '29c08560-35ac-40b1-be00-65c99cf91296', 'concept'::public.curated_course_node_type, 'Service climate, norms, stories, rituals, identity, inclusion, accountability, learning, and ethical culture', null, 1),
  ('b21fe87c-7c5f-4ce5-a427-41e1fe7df5c6', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '29c08560-35ac-40b1-be00-65c99cf91296', 'concept'::public.curated_course_node_type, 'Owner-operator, brand-franchisee, labor, vendor, community, government, and partner relationships', null, 2),
  ('1091e6a2-2f51-4761-8937-65c5420e7af5', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', null, 'topic'::public.curated_course_node_type, 'Business Models, Competitive Positioning, and Advantage', 'A business model explains who receives value, how it is delivered, and how the enterprise captures enough value to sustain the system. Students compare alternative positions and test whether choices reinforce one another.', 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('92826e62-89d4-4ddc-b92b-2d14322ac94f', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '1091e6a2-2f51-4761-8937-65c5420e7af5', 'subtopic'::public.curated_course_node_type, 'Hospitality business-model design', 'Students specify the customer, proposition, activities, resources, partners, economics, and governance of a hospitality concept.', 0),
  ('4bd2a230-abac-44a1-9abc-352ff54e83f9', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '92826e62-89d4-4ddc-b92b-2d14322ac94f', 'concept'::public.curated_course_node_type, 'Target guests, jobs-to-be-done, value proposition, channels, relationships, key activities, resources, and partners', null, 0),
  ('57fb6e89-ff7a-48a2-b293-c0cb6faa2442', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '92826e62-89d4-4ddc-b92b-2d14322ac94f', 'concept'::public.curated_course_node_type, 'Revenue model, pricing, unit economics, cost structure, working capital, asset intensity, scalability, and risk allocation', null, 1),
  ('8752124d-60d8-4b2a-ad4b-9bee57736d3a', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '92826e62-89d4-4ddc-b92b-2d14322ac94f', 'concept'::public.curated_course_node_type, 'Owned, leased, franchised, managed, licensed, membership, subscription, marketplace, aggregator, and hybrid models', null, 2),
  ('8adfe6e6-7c60-46fd-bbd6-4b849a37ee05', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '1091e6a2-2f51-4761-8937-65c5420e7af5', 'subtopic'::public.curated_course_node_type, 'Cost leadership, differentiation, and focus', 'This subtopic examines how firms create superior value through a deliberately configured activity system.', 1),
  ('cd148401-4c43-4dab-8b62-bf1c885a1b74', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '8adfe6e6-7c60-46fd-bbd6-4b849a37ee05', 'concept'::public.curated_course_node_type, 'Relative cost, economies of scale/scope/density/learning, capacity utilization, process design, and procurement', null, 0),
  ('5a8316e2-58bf-4fb6-953f-0446105e973b', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '8adfe6e6-7c60-46fd-bbd6-4b849a37ee05', 'concept'::public.curated_course_node_type, 'Brand meaning, experience, design, convenience, personalization, trust, location, community, quality, and innovation', null, 1),
  ('8812acc6-8139-40b3-aa65-3e241a39b341', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '8adfe6e6-7c60-46fd-bbd6-4b849a37ee05', 'concept'::public.curated_course_node_type, 'Broad versus focused scope, best-cost positions, strategic ambiguity, imitation, erosion, and being stuck in the middle', null, 2),
  ('12adca9a-cf94-44dc-b077-9cb30d7fb81f', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '1091e6a2-2f51-4761-8937-65c5420e7af5', 'subtopic'::public.curated_course_node_type, 'Value innovation and strategy testing', 'Students challenge inherited industry assumptions and test whether a proposed position is coherent, desirable, feasible, viable, and defensible.', 2),
  ('17e4e41f-2862-4b28-8c6f-8d53f6824aed', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '12adca9a-cf94-44dc-b077-9cb30d7fb81f', 'concept'::public.curated_course_node_type, 'Value curves, eliminate-reduce-raise-create, noncustomers, substitutes, complements, and pain points', null, 0),
  ('72992ecf-6ead-4206-a875-450d5d266485', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '12adca9a-cf94-44dc-b077-9cb30d7fb81f', 'concept'::public.curated_course_node_type, 'Strategic fit, tradeoffs, consistency, reinforcing activities, isolating mechanisms, and response scenarios', null, 1),
  ('998cab54-2f11-47da-ba96-b18aa9cd94bc', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '12adca9a-cf94-44dc-b077-9cb30d7fb81f', 'concept'::public.curated_course_node_type, 'Concept tests, pilots, minimum viable business model, leading indicators, kill criteria, and learning agenda', null, 2),
  ('ee1943c9-3196-4da7-b214-95503370572c', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', null, 'topic'::public.curated_course_node_type, 'Growth, Diversification, Vertical Scope, M&A, and Alliances', 'Growth creates value only when the firm has an advantage in the new activity and the benefits exceed complexity, capital, and execution risk. Students evaluate organic and inorganic pathways with explicit parenting logic.', 4),
  ('dd9e6042-a591-4aed-a65b-0d63a35f4de2', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'ee1943c9-3196-4da7-b214-95503370572c', 'subtopic'::public.curated_course_node_type, 'Organic growth and portfolio pathways', 'Students compare deeper penetration, new segments, new markets, new offers, and adjacent services.', 0),
  ('070e1974-2a3d-4f46-aed2-55f630841d42', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'dd9e6042-a591-4aed-a65b-0d63a35f4de2', 'concept'::public.curated_course_node_type, 'Market penetration, product development, market development, adjacency, replication, conversion, and new concept creation', null, 0),
  ('2db19938-1c58-4401-a425-6f1ddc167736', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'dd9e6042-a591-4aed-a65b-0d63a35f4de2', 'concept'::public.curated_course_node_type, 'Same-store growth, new units, white space, pipeline, ramp-up, cannibalization, saturation, and learning curve', null, 1),
  ('a466b9b9-f0c3-41dd-9736-dfca92ddda74', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'dd9e6042-a591-4aed-a65b-0d63a35f4de2', 'concept'::public.curated_course_node_type, 'Core, adjacent, transformational horizons; options, sequencing, stage gates, and resource commitments', null, 2),
  ('c8b647a1-6a16-4fe5-a542-4950a3070cb1', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'ee1943c9-3196-4da7-b214-95503370572c', 'subtopic'::public.curated_course_node_type, 'Diversification and vertical integration', 'This subtopic tests when corporate ownership creates more value than market contracting.', 1),
  ('49dbfabe-8d21-4984-8803-6314b724c934', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'c8b647a1-6a16-4fe5-a542-4950a3070cb1', 'concept'::public.curated_course_node_type, 'Related and unrelated diversification, economies of scope, shared activities, cross-selling, brand leverage, and internal capital markets', null, 0),
  ('1139de4d-0c79-43da-a390-44e96d6cbdff', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'c8b647a1-6a16-4fe5-a542-4950a3070cb1', 'concept'::public.curated_course_node_type, 'Backward and forward integration, transaction costs, hold-up, quality control, data, coordination, flexibility, and antitrust awareness', null, 1),
  ('c7194708-c56b-48bf-b209-934a90dea534', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'c8b647a1-6a16-4fe5-a542-4950a3070cb1', 'concept'::public.curated_course_node_type, 'Parenting advantage, better-off test, ownership test, complexity discount, bureaucracy, and divestiture', null, 2),
  ('d7a58011-8250-4fce-9348-f4acbe6344d5', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'ee1943c9-3196-4da7-b214-95503370572c', 'subtopic'::public.curated_course_node_type, 'Mergers, acquisitions, joint ventures, and alliances', 'Students examine target logic, valuation discipline, deal structure, integration, and post-deal accountability.', 2),
  ('b51ae0e5-f7a7-4e07-b948-dc05751bd4c4', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'd7a58011-8250-4fce-9348-f4acbe6344d5', 'concept'::public.curated_course_node_type, 'Build, buy, partner, license, franchise, joint venture, minority investment, management agreement, and strategic alliance', null, 0),
  ('db37cb37-99ca-40f2-9935-7d5dd0b5ba50', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'd7a58011-8250-4fce-9348-f4acbe6344d5', 'concept'::public.curated_course_node_type, 'Strategic fit, standalone value, synergies, control premium, diligence, financing, conditions, and downside case', null, 1),
  ('4bd42a8b-855a-48f4-a284-c991d73fd46f', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'd7a58011-8250-4fce-9348-f4acbe6344d5', 'concept'::public.curated_course_node_type, 'Integration thesis, culture, systems, talent, brand, customers, Day 1, milestones, synergy tracking, and exit', null, 2),
  ('73886c80-e5d0-4f42-87b8-c2eacd789cb6', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', null, 'topic'::public.curated_course_node_type, 'Brand Portfolio, Customer, Channel, and Commercial Strategy', 'Hospitality enterprises compete through portfolios of brands, relationships, channels, and revenue streams. Students align customer value and commercial systems with corporate strategy and property economics.', 5),
  ('cbf345e1-a317-4d03-a7a7-191dfb5e1fc0', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '73886c80-e5d0-4f42-87b8-c2eacd789cb6', 'subtopic'::public.curated_course_node_type, 'Brand architecture and portfolio roles', 'Students decide how brands cover segments without creating costly overlap or confusing guests, owners, and employees.', 0),
  ('b6a0bf9f-35f8-4e4a-93c8-86cca2a470dd', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'cbf345e1-a317-4d03-a7a7-191dfb5e1fc0', 'concept'::public.curated_course_node_type, 'Branded house, house of brands, endorsed brands, soft brands, collections, flags, outlet brands, and co-brands', null, 0),
