  ('675fe3db-74d0-4406-94d4-4a3fa7540f99', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'cbf345e1-a317-4d03-a7a7-191dfb5e1fc0', 'concept'::public.curated_course_node_type, 'Gap, overlap, cannibalization, extension, conversion, revitalization, retirement, and portfolio governance', null, 2),
  ('bd686bb6-cc23-42ba-9b3c-9e5d25f3c954', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '73886c80-e5d0-4f42-87b8-c2eacd789cb6', 'subtopic'::public.curated_course_node_type, 'Customer and channel strategy', 'This subtopic evaluates which demand to attract, how to reach it, and what relationships are worth building.', 1),
  ('975b4a66-0113-4aaa-9c0c-6a96cd29ffc0', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'bd686bb6-cc23-42ba-9b3c-9e5d25f3c954', 'concept'::public.curated_course_node_type, 'Segments, corporate accounts, groups, members, locals, residents, intermediaries, and lifetime value', null, 0),
  ('0f3cc29b-9e56-49de-be1a-3cec4e682d7e', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'bd686bb6-cc23-42ba-9b3c-9e5d25f3c954', 'concept'::public.curated_course_node_type, 'Direct, brand, OTA, GDS, wholesale, metasearch, delivery, membership, partnership, and loyalty channels', null, 1),
  ('664c9e63-7ea5-419e-bff5-8c38cd10adab', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'bd686bb6-cc23-42ba-9b3c-9e5d25f3c954', 'concept'::public.curated_course_node_type, 'Acquisition cost, commission, contribution, data access, retention, bargaining power, channel conflict, and incrementality', null, 2),
  ('0648d11c-4d7d-4dc3-8129-5896f501113d', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '73886c80-e5d0-4f42-87b8-c2eacd789cb6', 'subtopic'::public.curated_course_node_type, 'Commercial operating model', 'Students integrate marketing, sales, revenue management, distribution, CRM, and operations around shared enterprise goals.', 2),
  ('c6f18812-5d04-4e8b-b156-b9bdf0246d12', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '0648d11c-4d7d-4dc3-8129-5896f501113d', 'concept'::public.curated_course_node_type, 'Demand generation, pricing, inventory, group displacement, promotions, partnerships, and ancillary revenue', null, 0),
  ('35e55bcb-95ec-4a74-b284-aa2a3ed33c7b', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '0648d11c-4d7d-4dc3-8129-5896f501113d', 'concept'::public.curated_course_node_type, 'Commercial organization, decision rights, shared metrics, incentives, meeting cadence, forecast, and accountability', null, 1),
  ('7ca3e050-f401-481d-8150-fea6b3411ba2', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '0648d11c-4d7d-4dc3-8129-5896f501113d', 'concept'::public.curated_course_node_type, 'Top-line growth versus profitable demand, brand equity, guest trust, operational readiness, and owner return', null, 2),
  ('f8b9621f-9153-4a96-b002-abdbfc7009a7', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', null, 'topic'::public.curated_course_node_type, 'Ownership, Asset-Light Strategy, Contracts, and Hotel Asset Management', 'Hospitality strategy often separates real-estate ownership, brand, operations, distribution, and capital. Students learn how contracts allocate economics, control, risk, and incentives across the owner-brand-operator system.', 6),
  ('9ac82949-8707-471b-a974-f2f525445147', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'f8b9621f-9153-4a96-b002-abdbfc7009a7', 'subtopic'::public.curated_course_node_type, 'Ownership and operating structures', 'Students compare owned, leased, managed, franchised, licensed, and affiliated arrangements.', 0);
