  ('50d5d1bf-97d2-4d06-8902-e2ffa5c6a73c', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '2fe14201-0a3f-45f8-8400-434f4a1b1dd9', 'concept'::public.curated_course_node_type, 'Demand, demographics, connectivity, tourism policy, pipeline, competition, real estate, labor, infrastructure, and seasonality', null, 0),
