  ('4fd0912f-b991-457d-8b1a-027a5eea8065', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'bb83908c-d224-4242-84b5-10d27880b127', 'subtopic'::public.curated_course_node_type, 'Entry modes and international configuration', 'This subtopic matches control, commitment, learning, speed, and risk to the expansion vehicle.', 1),
  ('e926f34e-4fed-406c-bf84-dbdf0218a32a', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '4fd0912f-b991-457d-8b1a-027a5eea8065', 'concept'::public.curated_course_node_type, 'Export/licensing, franchise, master franchise, management contract, lease, acquisition, greenfield, alliance, and joint venture', null, 0),
