  ('5dc9e887-8e2a-4594-8dee-3a6b5ab30ab4', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'b0bfdf47-6780-4e17-adc0-4f12b193f0b9', 'concept'::public.curated_course_node_type, 'Local talent, supplier development, community license, institutional relationships, feedback, and reverse innovation', null, 2),
