  ('7949b61c-d7b5-474d-bac9-b35e42076faf', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '43ca3410-1a76-4868-baa6-d49ab552625c', 'subtopic'::public.curated_course_node_type, 'Strategy-to-finance logic', 'Students build a value-driver tree that links strategic choices to demand, pricing, operations, assets, investment, risk, and cash flow.', 0),
