  ('2a5ad9a6-0b56-4427-a0d8-e67ee18ca523', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '7949b61c-d7b5-474d-bac9-b35e42076faf', 'concept'::public.curated_course_node_type, 'Working capital, maintenance capex, growth capex, asset turns, capital intensity, taxes, fees, and financing', null, 1),
  ('2b40e5ff-043f-4f4c-afa0-2a00bd151037', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '7949b61c-d7b5-474d-bac9-b35e42076faf', 'concept'::public.curated_course_node_type, 'Return on invested capital, cost of capital, economic profit, free cash flow, growth duration, and value creation', null, 2),
  ('9db03233-d9a9-4cd4-aa9c-c17fc6fb0234', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '43ca3410-1a76-4868-baa6-d49ab552625c', 'subtopic'::public.curated_course_node_type, 'Valuation and strategic alternatives', 'This subtopic uses valuation as a disciplined comparison of futures, not a single precise answer.', 1),
  ('d01a4015-ce25-4d62-b202-446c77232129', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '9db03233-d9a9-4cd4-aa9c-c17fc6fb0234', 'concept'::public.curated_course_node_type, 'Incremental cash flows, DCF, terminal value, multiples, precedent transactions, replacement cost, and sum of parts', null, 0),
  ('e42078d8-ad5c-4c82-9088-5ff0b8423f38', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '9db03233-d9a9-4cd4-aa9c-c17fc6fb0234', 'concept'::public.curated_course_node_type, 'Base, upside, downside, stress, break-even, sensitivity, probability, real options, and strategic option value', null, 1),
