  ('230f84fa-6717-41bd-a0f9-dbec7d7054b3', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'bbc6092d-06d7-4b19-a2bf-4f45d5c976b1', 'concept'::public.curated_course_node_type, 'Strategic fit, expected return, risk, liquidity, capacity, dependencies, timing, optionality, and stakeholder impact', null, 0),
  ('f273a48c-45c4-4929-a3c2-0c0cf83e07d8', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'bbc6092d-06d7-4b19-a2bf-4f45d5c976b1', 'concept'::public.curated_course_node_type, 'Capital rationing, hurdle rates, ranking bias, portfolio balance, debt capacity, dividends, buybacks, and covenant awareness', null, 1),
  ('d1ba8466-99cd-4554-bb1d-f73735cbf558', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'bbc6092d-06d7-4b19-a2bf-4f45d5c976b1', 'concept'::public.curated_course_node_type, 'Approval gates, investment committee, post-audit, benefit realization, reallocation, sunk-cost discipline, and exit', null, 2),
  ('13868d59-53ba-433c-945f-93fe6dacd0b6', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', null, 'topic'::public.curated_course_node_type, 'Innovation, Entrepreneurship, Digital Platforms, and Responsible AI', 'Innovation changes the guest proposition, operating system, business model, or industry architecture. Students learn to search, test, scale, and govern innovation while avoiding technology theater.', 9),
  ('6df04af5-9e66-4241-9aef-2669052f0833', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '13868d59-53ba-433c-945f-93fe6dacd0b6', 'subtopic'::public.curated_course_node_type, 'Innovation strategy and ambidexterity', 'Students balance exploitation of the current model with exploration of new opportunities.', 0),
  ('12ff463c-fd67-420d-b6a0-c52fff350e2f', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '6df04af5-9e66-4241-9aef-2669052f0833', 'concept'::public.curated_course_node_type, 'Incremental, architectural, radical, disruptive, sustaining, process, experience, business-model, and ecosystem innovation', null, 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('f78c3eb6-6f2e-45a2-a7c2-d52f873dbe06', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '6df04af5-9e66-4241-9aef-2669052f0833', 'concept'::public.curated_course_node_type, 'Search domains, portfolio thesis, core-adjacent-transformational horizons, ambidexterity, resource separation, and senior sponsorship', null, 1),
  ('9676d9d0-6f5c-4549-87f1-8bc21ce0de88', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '6df04af5-9e66-4241-9aef-2669052f0833', 'concept'::public.curated_course_node_type, 'Idea funnel, evidence gates, experiment velocity, failure learning, scale readiness, and innovation accounting', null, 2),
  ('e7de842c-069c-4ac7-be34-dc6c62ebe435', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '13868d59-53ba-433c-945f-93fe6dacd0b6', 'subtopic'::public.curated_course_node_type, 'Entrepreneurship and venture design', 'This subtopic treats new ventures as hypotheses about guests, problems, solutions, channels, economics, and defensibility.', 1),
  ('deb9175a-774b-44ab-8725-428b1d0202e9', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'e7de842c-069c-4ac7-be34-dc6c62ebe435', 'concept'::public.curated_course_node_type, 'Opportunity recognition, founder-market fit, customer discovery, value proposition, prototype, MVP, and business-model testing', null, 0),
  ('f1777170-68b6-4577-b64e-1c9f12aeb622', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'e7de842c-069c-4ac7-be34-dc6c62ebe435', 'concept'::public.curated_course_node_type, 'Unit economics, cash runway, funding, milestones, partnerships, intellectual property, regulatory pathway, and go-to-market', null, 1),
  ('f541b016-dc15-463b-9190-5ba825ee6910', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'e7de842c-069c-4ac7-be34-dc6c62ebe435', 'concept'::public.curated_course_node_type, 'Pivot, persevere, pause, partner, spin out, acquire, integrate, or shut down', null, 2),
  ('6a22abf6-ee0f-425f-870c-dbf4fb10e63c', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '13868d59-53ba-433c-945f-93fe6dacd0b6', 'subtopic'::public.curated_course_node_type, 'Digital, data, platforms, automation, and AI', 'Students evaluate technology investments by strategic outcome, operating fit, data, adoption, control, and trust.', 2),
  ('b0d696cc-c8dc-4019-a901-1e605ca04b6b', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '6a22abf6-ee0f-425f-870c-dbf4fb10e63c', 'concept'::public.curated_course_node_type, 'PMS/POS/CRS/RMS/CRM, cloud, APIs, data platforms, mobile, robotics, IoT, digital identity, and cybersecurity', null, 0),
  ('a4fd18f3-3313-4340-a7ad-69ad6a4b1d1b', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '6a22abf6-ee0f-425f-870c-dbf4fb10e63c', 'concept'::public.curated_course_node_type, 'Network effects, marketplaces, platform governance, interoperability, switching costs, vendor lock-in, data rights, and build-buy-partner', null, 1),
  ('2808843f-7eb8-4a59-8e88-5786699498ac', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '6a22abf6-ee0f-425f-870c-dbf4fb10e63c', 'concept'::public.curated_course_node_type, 'AI use cases, accuracy, bias, privacy, explainability, human oversight, hallucination, security, workforce effects, and NIST AI RMF', null, 2),
  ('e9f86cb9-0998-4786-a3cb-d22eac262907', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', null, 'topic'::public.curated_course_node_type, 'Organization Design, Leadership, Change, and Strategy Execution', 'A strategy has no effect until resources, structures, incentives, capabilities, routines, and leadership behavior make it real. Students design an execution system that can deliver today while adapting tomorrow.', 10),
  ('14dc2144-4ac5-42bb-8754-6fd259ae1177', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'e9f86cb9-0998-4786-a3cb-d22eac262907', 'subtopic'::public.curated_course_node_type, 'Organization and operating-model design', 'Students align structure and decision rights with strategic priorities, scale, geography, brands, assets, and capabilities.', 0),
  ('121051ee-1938-4d80-be3d-e5a6bea2b586', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '14dc2144-4ac5-42bb-8754-6fd259ae1177', 'concept'::public.curated_course_node_type, 'Functional, divisional, geographic, brand, property, matrix, network, platform, and shared-service structures', null, 0),
  ('ce0e47ae-7621-4ebb-84e9-d0e711b03079', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '14dc2144-4ac5-42bb-8754-6fd259ae1177', 'concept'::public.curated_course_node_type, 'Centralize versus decentralize, spans/layers, governance forums, decision rights, interfaces, service levels, and escalation', null, 1),
  ('9f643211-0cfe-43b1-a77d-7c8ca569ae21', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '14dc2144-4ac5-42bb-8754-6fd259ae1177', 'concept'::public.curated_course_node_type, 'Corporate center roles, parenting, centers of excellence, field support, owner relations, and accountability', null, 2),
  ('f90c3790-5de3-45b0-99ce-2e4e2984756e', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'e9f86cb9-0998-4786-a3cb-d22eac262907', 'subtopic'::public.curated_course_node_type, 'Strategic leadership and culture', 'This subtopic examines how leaders create direction, alignment, commitment, trust, learning, and ethical boundaries.', 1),
  ('41480512-7f29-4d41-8a1a-c0ac20e11fa0', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'f90c3790-5de3-45b0-99ce-2e4e2984756e', 'concept'::public.curated_course_node_type, 'Strategic intent, sensemaking, communication, coalition, role modeling, resource choices, consistency, and humility', null, 0),
  ('c36f2477-5173-4b2c-a03e-7947ca52349a', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'f90c3790-5de3-45b0-99ce-2e4e2984756e', 'concept'::public.curated_course_node_type, 'Culture diagnosis, desired behaviors, systems reinforcement, psychological safety, inclusion, challenge, voice, and accountability', null, 1),
  ('e3fb0d83-4d9c-41c6-8f5a-bbac339dad97', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'f90c3790-5de3-45b0-99ce-2e4e2984756e', 'concept'::public.curated_course_node_type, 'Board, executives, owners, general managers, department leaders, frontline employees, and distributed leadership', null, 2),
  ('b8696733-4b97-4775-b99e-665a371efaaf', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'e9f86cb9-0998-4786-a3cb-d22eac262907', 'subtopic'::public.curated_course_node_type, 'Execution, change, and performance management', 'Students translate priorities into initiatives, measures, owners, milestones, learning loops, and corrective action.', 2),
  ('4aa52806-e18b-4004-886c-d2cbbc60dbab', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'b8696733-4b97-4775-b99e-665a371efaaf', 'concept'::public.curated_course_node_type, 'Strategy map, objectives, key results, balanced scorecard, initiative portfolio, RACI, roadmap, and dependency map', null, 0),
  ('b9680305-b890-4d84-b6e0-7b70256585ea', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'b8696733-4b97-4775-b99e-665a371efaaf', 'concept'::public.curated_course_node_type, 'Stakeholder analysis, change story, participation, communication, training, resistance, incentives, adoption, and reinforcement', null, 1),
  ('2dbd7273-b387-491c-9c7b-e1dab9e43b37', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'b8696733-4b97-4775-b99e-665a371efaaf', 'concept'::public.curated_course_node_type, 'Leading/lagging indicators, review cadence, variance, benefits, agile adaptation, stop-start-continue decisions, and after-action review', null, 2),
  ('20691f3f-d15a-47a0-9599-7a16ebaf6d44', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', null, 'topic'::public.curated_course_node_type, 'Risk, Scenarios, Resilience, Cybersecurity, and Crisis Strategy', 'Hospitality enterprises face demand shocks, disasters, cyber events, climate hazards, health crises, geopolitical disruption, and operational failures. Students integrate risk and resilience into strategy instead of treating them as separate compliance exercises.', 11),
  ('18e5d6a7-45a9-41df-8419-5f44e61c0dec', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '20691f3f-d15a-47a0-9599-7a16ebaf6d44', 'subtopic'::public.curated_course_node_type, 'Enterprise risk and strategic uncertainty', 'Students identify threats and opportunities, their causes, velocity, interdependencies, ownership, and potential response.', 0),
  ('7f5a9eae-1f77-4bfe-9356-4f8e8e56c0de', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '18e5d6a7-45a9-41df-8419-5f44e61c0dec', 'concept'::public.curated_course_node_type, 'Strategic, financial, operational, legal, cyber, privacy, safety, people, third-party, reputational, climate, and geopolitical risk', null, 0),
  ('1b89f62c-6e7a-47b3-a7d2-504ca1be5ef6', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '18e5d6a7-45a9-41df-8419-5f44e61c0dec', 'concept'::public.curated_course_node_type, 'Likelihood, impact, velocity, persistence, detectability, correlation, concentration, risk appetite, tolerance, and capacity', null, 1),
  ('e40c2614-9099-410f-9f6a-e55811715443', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '18e5d6a7-45a9-41df-8419-5f44e61c0dec', 'concept'::public.curated_course_node_type, 'Risk register, heat map limitations, bow-tie, stress testing, reverse stress, key risk indicators, and assurance', null, 2),
  ('2dd5ad7f-6af8-43f4-8d03-1b2173200fde', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '20691f3f-d15a-47a0-9599-7a16ebaf6d44', 'subtopic'::public.curated_course_node_type, 'Scenario planning and strategic options', 'This subtopic develops strategies that remain coherent across plausible futures and preserves choices when uncertainty is high.', 1),
  ('447ab074-f823-437c-a405-b5bb951a8df3', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '2dd5ad7f-6af8-43f4-8d03-1b2173200fde', 'concept'::public.curated_course_node_type, 'Critical uncertainties, scenario matrix, narratives, quantitative implications, competitor behavior, stakeholder response, and signposts', null, 0),
  ('bb009b4f-4d9d-4d1b-92c3-3cb723b945c0', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '2dd5ad7f-6af8-43f4-8d03-1b2173200fde', 'concept'::public.curated_course_node_type, 'Robust actions, contingent actions, no-regret moves, hedges, real options, staged commitments, and trigger points', null, 1),
  ('43e4f577-e632-43e2-84b1-6f4079614db0', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '2dd5ad7f-6af8-43f4-8d03-1b2173200fde', 'concept'::public.curated_course_node_type, 'Wild cards, black swans, premortem, red team, sensitivity, decision trees, and continuous monitoring', null, 2),
  ('9f2bb32e-85dd-4d05-a29a-fda768a7f246', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '20691f3f-d15a-47a0-9599-7a16ebaf6d44', 'subtopic'::public.curated_course_node_type, 'Resilience and crisis leadership', 'Students plan for continuity, adaptation, recovery, and renewal across properties, systems, people, suppliers, and destinations.', 2),
  ('a3f36c7b-74b9-4645-83a1-a5717b296d17', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '9f2bb32e-85dd-4d05-a29a-fda768a7f246', 'concept'::public.curated_course_node_type, 'Business impact analysis, critical services, dependencies, redundancy, backup, alternate suppliers, remote capability, and recovery objectives', null, 0),
  ('8122f640-e05e-4adb-beec-f7c6f2bd8447', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '9f2bb32e-85dd-4d05-a29a-fda768a7f246', 'concept'::public.curated_course_node_type, 'Emergency command, safety, communication, guest care, employee support, cyber response, insurance, documentation, and stakeholder coordination', null, 1),
  ('c343c6e1-7d68-45ef-ba43-89fa4a74028d', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '9f2bb32e-85dd-4d05-a29a-fda768a7f246', 'concept'::public.curated_course_node_type, 'Climate adaptation, physical and transition risk, destination resilience, recovery sequencing, after-action learning, and trust repair', null, 2),
  ('7cf4e1bc-e0de-404d-a34e-744f64ba092d', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', null, 'topic'::public.curated_course_node_type, 'Ethics, Corporate Governance, Stakeholders, and Sustainable Value', 'Hospitality strategy affects guests, employees, owners, communities, suppliers, destinations, and the environment. Students evaluate legitimacy, governance, distributional effects, and long-term value alongside financial performance.', 12),
  ('93b4145d-fe4f-41df-b911-f1790e3fb44a', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '7cf4e1bc-e0de-404d-a34e-744f64ba092d', 'subtopic'::public.curated_course_node_type, 'Ethical strategic decision making', 'Students make values, duties, consequences, rights, justice, conflicts, and affected stakeholders explicit.', 0),
  ('ccbdb78b-4450-4665-8064-097df7ee63f2', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '93b4145d-fe4f-41df-b911-f1790e3fb44a', 'concept'::public.curated_course_node_type, 'Legal minimum versus ethical responsibility, fiduciary duties, professional judgment, conflicts of interest, and speaking up', null, 0),
  ('7e72e317-d9c6-4c43-9652-28a4b9634a22', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '93b4145d-fe4f-41df-b911-f1790e3fb44a', 'concept'::public.curated_course_node_type, 'Guest safety, labor practices, accessibility, discrimination, pricing fairness, privacy, surveillance, corruption, and human rights', null, 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('8ce8339e-27a4-410c-abe2-955484c22234', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '93b4145d-fe4f-41df-b911-f1790e3fb44a', 'concept'::public.curated_course_node_type, 'Stakeholder mapping, options, harms/benefits, reversibility, precedent, transparency, challenge, escalation, and documentation', null, 2),
  ('d08130d1-1f3d-4283-b23e-1455d0a92565', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '7cf4e1bc-e0de-404d-a34e-744f64ba092d', 'subtopic'::public.curated_course_node_type, 'Boards, owners, controls, and governance', 'This subtopic clarifies oversight, accountability, incentives, information quality, and checks on managerial power.', 1),
  ('05db5053-83a8-4751-ae17-c467d421065a', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'd08130d1-1f3d-4283-b23e-1455d0a92565', 'concept'::public.curated_course_node_type, 'Board roles, independence, committees, executive authority, owner representation, franchise councils, and stakeholder forums', null, 0),
  ('8a853fac-5bd4-4aec-a4ea-5c9a96788026', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'd08130d1-1f3d-4283-b23e-1455d0a92565', 'concept'::public.curated_course_node_type, 'Strategy oversight, risk, succession, compensation, audit/internal control, cyber, data, AI, sustainability, and crisis governance', null, 1),
  ('9bae8974-5eb5-4e1f-9f6b-54d0d18278f6', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'd08130d1-1f3d-4283-b23e-1455d0a92565', 'concept'::public.curated_course_node_type, 'Information asymmetry, agency problems, related parties, incentives, misconduct, whistleblowing, assurance, and board evaluation', null, 2),
  ('6fe5eb08-18c6-4f88-a743-d1db0a271495', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '7cf4e1bc-e0de-404d-a34e-744f64ba092d', 'subtopic'::public.curated_course_node_type, 'Sustainability, impact, and shared value', 'Students integrate environmental and social dependencies into business-model, investment, supply-chain, and destination choices.', 2),
  ('96ca8fdf-4760-42a4-90cc-e295b624133f', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '6fe5eb08-18c6-4f88-a743-d1db0a271495', 'concept'::public.curated_course_node_type, 'Energy, water, waste, food loss, carbon, biodiversity, sourcing, labor, community, housing, overtourism, and cultural heritage', null, 0),
  ('12a07583-088e-4368-92b8-d47f6ab39351', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '6fe5eb08-18c6-4f88-a743-d1db0a271495', 'concept'::public.curated_course_node_type, 'Materiality, boundaries, baselines, targets, transition plans, life-cycle cost, circularity, resilience, and credible claims', null, 1),
  ('45f4be70-abff-434e-8c7c-6db082d4a07a', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', '6fe5eb08-18c6-4f88-a743-d1db0a271495', 'concept'::public.curated_course_node_type, 'Stakeholder outcomes, tradeoffs, distributional impact, greenwashing, measurement, assurance, policy, and value creation', null, 2),
  ('e30ca45a-df7b-4102-803c-ed4e01ce4f3d', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', null, 'topic'::public.curated_course_node_type, 'Integrative Hospitality Strategy Case and Board-Level Communication', 'The capstone requires students to diagnose a real or realistic enterprise, choose among credible alternatives, quantify consequences, design execution, and defend the recommendation under challenge.', 13),
  ('943d1f98-a833-469f-8bd5-b695f8097253', 'b3c4d5e6-7f8a-4b18-9c07-1d2e3f4a5b08', 'e30ca45a-df7b-4102-803c-ed4e01ce4f3d', 'subtopic'::public.curated_course_node_type, 'Case analysis and evidence synthesis', 'Students move from a large evidence set to the few material issues that determine the decision.', 0),
